 fn truncate_to_width(text: &str, width: usize) -> String {
     text.chars().take(width).collect()
 }
+
+fn line_char_len(line: &str) -> usize {
+    line.chars().count()
+}
+
+fn pane_lines_from_text(text: &str) -> Vec<String> {
+    if text.is_empty() {
+        vec![String::new()]
+    } else {
+        text.lines().map(str::to_string).collect()
+    }
+}
+
+fn clamp_position_to_lines(position: TextPosition, lines: &[String]) -> TextPosition {
+    let row = position.row.min(lines.len().saturating_sub(1));
+    TextPosition {
+        row,
+        column: position.column.min(line_char_len(&lines[row])),
+    }
+}
+
+fn apply_delta(value: usize, delta: isize) -> usize {
+    if delta < 0 {
+        value.saturating_sub((-delta) as usize)
+    } else {
+        value.saturating_add(delta as usize)
+    }
+}
+
+fn ordered_positions(
+    anchor: TextPosition,
+    cursor: TextPosition,
+) -> (TextPosition, TextPosition) {
+    if (anchor.row, anchor.column) <= (cursor.row, cursor.column) {
+        (anchor, cursor)
+    } else {
+        (cursor, anchor)
+    }
+}
+
+fn selection_ranges_for_line(
+    selection: VisualSelection,
+    row_index: usize,
+    line: &str,
+) -> Vec<(usize, usize)> {
+    let line_len = line_char_len(line);
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection.anchor.row.max(selection.cursor.row);
+    if row_index < start_row || row_index > end_row {
+        return Vec::new();
+    }
+
+    match selection.kind {
+        VisualKind::Line => (!line.is_empty()).then_some((0, line_len)).into_iter().collect(),
+        VisualKind::Block => {
+            let start = selection.anchor.column.min(selection.cursor.column).min(line_len);
+            let end = selection
+                .anchor
+                .column
+                .max(selection.cursor.column)
+                .saturating_add(1)
+                .min(line_len);
+            (start < end).then_some((start, end)).into_iter().collect()
+        }
+        VisualKind::Character => {
+            let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+            let range = if start.row == end.row {
+                let range_start = start.column.min(line_len);
+                let range_end = end.column.saturating_add(1).min(line_len);
+                (range_start < range_end).then_some((range_start, range_end))
+            } else if row_index == start.row {
+                let range_start = start.column.min(line_len);
+                (range_start < line_len).then_some((range_start, line_len))
+            } else if row_index == end.row {
+                let range_end = end.column.saturating_add(1).min(line_len);
+                (range_end > 0).then_some((0, range_end))
+            } else {
+                (!line.is_empty()).then_some((0, line_len))
+            };
+            range.into_iter().collect()
+        }
+    }
+}
+
+fn selected_text_from_lines(selection: VisualSelection, lines: &[String]) -> String {
+    if lines.is_empty() {
+        return String::new();
+    }
+    let anchor = clamp_position_to_lines(selection.anchor, lines);
+    let cursor = clamp_position_to_lines(selection.cursor, lines);
+    let selection = VisualSelection {
+        anchor,
+        cursor,
+        ..selection
+    };
+    let start_row = anchor.row.min(cursor.row);
+    let end_row = anchor.row.max(cursor.row);
+
+    match selection.kind {
+        VisualKind::Line => lines[start_row..=end_row].join("\n"),
+        VisualKind::Block => {
+            let start_column = anchor.column.min(cursor.column);
+            let end_column = anchor.column.max(cursor.column);
+            lines[start_row..=end_row]
+                .iter()
+                .map(|line| slice_chars(line, start_column, end_column.saturating_add(1)))
+                .collect::<Vec<_>>()
+                .join("\n")
+        }
+        VisualKind::Character => {
+            let (start, end) = ordered_positions(anchor, cursor);
+            if start.row == end.row {
+                return slice_chars(
+                    &lines[start.row],
+                    start.column,
+                    end.column.saturating_add(1),
+                );
+            }
+
+            let mut selected = Vec::new();
+            selected.push(slice_chars(
+                &lines[start.row],
+                start.column,
+                line_char_len(&lines[start.row]),
+            ));
+            if end.row > start.row + 1 {
+                selected.extend(lines[start.row + 1..end.row].iter().cloned());
+            }
+            selected.push(slice_chars(
+                &lines[end.row],
+                0,
+                end.column.saturating_add(1),
+            ));
+            selected.join("\n")
+        }
+    }
+}
+
+fn slice_chars(line: &str, start: usize, end: usize) -> String {
+    line.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn styled_line_with_ranges(
+    line: &str,
+    base_reversed: bool,
+    ranges: &[(usize, usize)],
+) -> Spans<'static> {
+    let base_style = if base_reversed {
+        Style::default().add_modifier(Modifier::REVERSED)
+    } else {
+        Style::default()
+    };
+    let selected_style = Style::default().add_modifier(Modifier::REVERSED);
+    if ranges.is_empty() {
+        return Spans::from(vec![Span::styled(line.to_string(), base_style)]);
+    }
+
+    let mut spans = Vec::new();
+    let mut cursor = 0;
+    let line_len = line_char_len(line);
+    for (start, end) in ranges {
+        let start = (*start).min(line_len);
+        let end = (*end).min(line_len);
+        if cursor < start {
+            spans.push(Span::styled(slice_chars(line, cursor, start), base_style));
+        }
+        if start < end {
+            spans.push(Span::styled(slice_chars(line, start, end), selected_style));
+        }
+        cursor = cursor.max(end);
+    }
+    if cursor < line_len {
+        spans.push(Span::styled(slice_chars(line, cursor, line_len), base_style));
+    }
+    Spans::from(spans)
+}
+
+fn osc52_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = *chunk.get(1).unwrap_or(&0);
+        let third = *chunk.get(2).unwrap_or(&0);
+        let triple = ((first as u32) << 16) | ((second as u32) << 8) | third as u32;
+        encoded.push(TABLE[((triple >> 18) & 0x3f) as usize] as char);
+        encoded.push(TABLE[((triple >> 12) & 0x3f) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(TABLE[((triple >> 6) & 0x3f) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(TABLE[(triple & 0x3f) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}

